// Lithuanian recurring filing deadlines, computed relative to today. Static rules, no AI.
const today = new Date();
const y = today.getFullYear(), m = today.getMonth();
const iso = d => d.toISOString().slice(0, 10);
const nextOnDay = (day) => { let d = new Date(y, m, day); if (d < today) d = new Date(y, m + 1, day); return d; };
const items = [
  { filing: 'VAT return (FR0600) + VAT payment', rule: 'by the 25th of the following month', next: nextOnDay(25) },
  { filing: 'i.SAF invoice registers (VMI)', rule: 'by the 20th of the following month', next: nextOnDay(20) },
  { filing: 'GPM313 monthly income-tax return', rule: 'by the 15th of the following month', next: nextOnDay(15) },
  { filing: 'SODRA SAM report + contributions', rule: 'by the 15th of the following month', next: nextOnDay(15) },
  { filing: 'PLN204 corporate income tax (annual)', rule: 'by 15 June for the previous year', next: (() => { let d = new Date(y, 5, 15); if (d < today) d = new Date(y + 1, 5, 15); return d; })() },
];
const days = d => Math.ceil((d - today) / 86400000);
return JSON.stringify({ today: iso(today), deadlines: items.map(i => ({ ...i, next: iso(i.next), days_left: days(i.next) })) }, null, 2);
